"""Draft fix DDL for a drift event. Drafts only: a person reviews and runs them.

Fixes are template-generated, not AI-generated, so the SQL is predictable.
The AI layer explains the drift; it never writes the DDL that gets run.
"""

from __future__ import annotations

from .models import Comparison, DriftEvent, DriftType
from .rules import _as_decimal
from .types import NormType, normalize

HEADER = (
    "-- DRAFT generated by snowdrift for {id}: {label}\n"
    "-- Review before running. Test on a clone first. Never run against production without a change ticket.\n"
    "-- Run it with the right database/catalog selected (USE ...).\n"
)


def render_type(t: NormType, dialect: str) -> str:
    f = t.family
    if dialect == "snowflake":
        return {
            "STRING": f"VARCHAR({t.length})" if t.length else "VARCHAR",
            "CLOB": "VARCHAR",
            "INT": f"NUMBER({t.precision},0)" if t.precision else "NUMBER(38,0)",
            "DECIMAL": f"NUMBER({t.precision},{t.scale or 0})" if t.precision else "NUMBER",
            "FLOAT": "FLOAT",
            "DATE": "DATE",
            "TIMESTAMP": "TIMESTAMP_NTZ",
            "TIME": "TIME",
            "BOOLEAN": "BOOLEAN",
            "BINARY": "BINARY",
            "SEMI": "VARIANT",
        }.get(f, f)
    if dialect == "databricks":
        if f == "INT":
            p = t.precision or 10
            for limit, name in ((3, "TINYINT"), (5, "SMALLINT"), (10, "INT"), (19, "BIGINT")):
                if p <= limit:
                    return name
            return f"DECIMAL({p},0)"
        return {
            "STRING": "STRING",
            "CLOB": "STRING",
            "DECIMAL": f"DECIMAL({t.precision},{t.scale or 0})" if t.precision else "DECIMAL(38,0)",
            "FLOAT": "DOUBLE",
            "DATE": "DATE",
            "TIMESTAMP": "TIMESTAMP",
            "TIME": "STRING",
            "BOOLEAN": "BOOLEAN",
            "BINARY": "BINARY",
            "SEMI": "STRING",
        }.get(f, f)
    return str(t)


def _manual(event: DriftEvent, fq: str, dialect: str) -> str:
    clone = f"CREATE TABLE {fq}_BKP CLONE {fq};" if dialect == "snowflake" else f"CREATE TABLE {fq}_bkp DEEP CLONE {fq};"
    return (
        f"-- No safe in-place change for {event.drift_type.value} ({event.value_a} -> {event.value_b}).\n"
        "-- Suggested pattern: back up, recreate with the new definition, reload, check counts, drop the backup.\n"
        f"-- {clone}\n"
    )


def _q(name: str, dialect: str) -> str:
    """Quote an identifier so reserved words (ORDER, DATE...) still work."""
    return f"`{name}`" if dialect == "databricks" else f'"{name}"'


def _widens(ta: NormType, tb: NormType) -> bool:
    """True if changing B to A's type only widens it (no lost whole digits or decimal places)."""
    ta, tb = _as_decimal(ta), _as_decimal(tb)
    if ta.precision is None or tb.precision is None:
        return False
    sa, sb = ta.scale or 0, tb.scale or 0
    return sa >= sb and (ta.precision - sa) >= (tb.precision - sb)


def draft_fix(event: DriftEvent, dialects: dict[str, str]) -> str | None:
    """Return draft SQL that brings side B in line with side A, or None if no fix applies."""
    if event.comparison not in (Comparison.CROSS_PLATFORM, Comparison.LAYER):
        return None
    dialect = dialects.get(event.platform_b, event.platform_b)
    if dialect not in ("snowflake", "databricks"):
        return None
    table = _q(event.table, dialect)
    fq = f"{_q(event.schema_b, dialect)}.{table}" if event.schema_b else table
    col = _q(event.column, dialect) if event.column else None
    head = HEADER.format(id=event.drift_id, label=event.label())
    dt = event.drift_type

    if dt is DriftType.COLUMN_MISSING and event.col_a:
        typ = render_type(normalize(event.col_a), dialect)
        if typ.startswith("UNKNOWN"):
            return head + f"-- Source type {event.col_a.raw_type!r} has no mapping yet; add the column by hand.\n"
        body = (
            f"ALTER TABLE {fq} ADD COLUMN {col} {typ};\n"
            if dialect == "snowflake"
            else f"ALTER TABLE {fq} ADD COLUMNS ({col} {typ});\n"
        )
        return head + body
    if dt is DriftType.LENGTH_SHRUNK and event.col_a:
        if dialect == "snowflake":
            return head + f"ALTER TABLE {fq} ALTER COLUMN {col} SET DATA TYPE {render_type(normalize(event.col_a), dialect)};\n"
        return head + "-- Databricks STRING has no length limit; if the column is VARCHAR(n), change it to STRING or recreate.\n"
    if dt is DriftType.PRECISION_SHRUNK and event.col_a and event.col_b:
        ta, tb = normalize(event.col_a), normalize(event.col_b)
        typ = render_type(_as_decimal(ta), dialect)
        same_scale = (_as_decimal(ta).scale or 0) == (_as_decimal(tb).scale or 0)
        if dialect == "snowflake" and same_scale and _widens(ta, tb):
            return head + f"ALTER TABLE {fq} ALTER COLUMN {col} SET DATA TYPE {typ};\n"
        if dialect == "databricks" and _widens(ta, tb):
            return head + (
                "-- Needs Delta type widening (check your runtime supports it).\n"
                f"ALTER TABLE {fq} SET TBLPROPERTIES ('delta.enableTypeWidening' = 'true');\n"
                f"ALTER TABLE {fq} ALTER COLUMN {col} TYPE {typ};\n"
            )
        return head + _manual(event, fq, dialect)
    if dt is DriftType.NULLABILITY_CHANGED and event.comparison is Comparison.CROSS_PLATFORM and event.value_b == "NOT NULL":
        return head + f"ALTER TABLE {fq} ALTER COLUMN {col} DROP NOT NULL;\n"
    if dt is DriftType.POSSIBLE_RENAME:
        note = "" if dialect == "snowflake" else "-- Databricks needs column mapping enabled to rename columns.\n"
        old, new = _q(event.value_b, dialect), _q(event.value_a, dialect)
        return (
            head + "-- Confirm this really is a rename first.\n" + note + f"-- ALTER TABLE {fq} RENAME COLUMN {old} TO {new};\n"
        )
    if dt is DriftType.COLUMN_EXTRA:
        return head + (
            f"-- {event.column} exists in {event.side_b} but not in {event.side_a}.\n"
            "-- If it was retired upstream, confirm nothing reads it, then:\n"
            f"-- ALTER TABLE {fq} DROP COLUMN {col};\n"
        )
    if dt is DriftType.TYPE_CHANGED:
        return head + _manual(event, fq, dialect)
    return None
